/// 是否是decl的开始，前面是分界符号
let is_new_decl = function
    | "->" | "=" | "LLPAREN" -> false
    | _ -> true

let follow_semicolon: string Set =
  set ["!";"(";")";"+";"-";"ALWAYS_PREFIX";"EOF";"FUN";"IDENT";"LET";"LITERAL";"MATCH";"OPEN";"RRPAREN";"[";"[|";"]";"|]"]
let precede_semicolon: string Set =
  set [")";">";"IDENT";"LITERAL";"RHSEND";"RRPAREN";"]";"|]"]
let precede_declExpr: string Set = set ["(";";";"LLPAREN";"[";"[|"]
let first_declExpr: string Set = set ["!";"(";"+";"-";"ALWAYS_PREFIX";"FUN";"IDENT";"LET";"LITERAL";"MATCH";"[";"[|"]
let first_valueExpr: string Set = set ["!";"(";"+";"-";"ALWAYS_PREFIX";"FUN";"IDENT";"LITERAL";"[";"[|"]
let first_appExpr = set ["(";"IDENT";"LITERAL";"[";"[|"]
let last_appExpr = set [")";">";"IDENT";"LITERAL";"]";"|]"]
let module_statement: string list Set = set [
  ["IDENT";".";"revLongid";"MODULE"]
  ["IDENT";"MODULE"]
]
let open_statement: string list Set = set [
  ["IDENT";".";"revLongid";"OPEN"]
  ["IDENT";"OPEN"]
]
